void AssemblyWriter::printModule(const Module *M) {
  Machine.initializeIfNeeded();

  if (ShouldPreserveUseListOrder)
    UseListOrders = predictUseListOrder(M);

  if (!M->getModuleIdentifier().empty() &&
      // Don't print the ID if it will start a new line (which would
      // require a comment char before it).
      M->getModuleIdentifier().find('\n') == std::string::npos)
    Out << "; ModuleID = '" << M->getModuleIdentifier() << "'\n";

  if (!M->getSourceFileName().empty()) {
    Out << "source_filename = \"";
    printEscapedString(M->getSourceFileName(), Out);
    Out << "\"\n";
  }

  const std::string &DL = M->getDataLayoutStr();
  if (!DL.empty())
    Out << "target datalayout = \"" << DL << "\"\n";
  if (!M->getTargetTriple().empty())
    Out << "target triple = \"" << M->getTargetTriple().str() << "\"\n";

  if (M->hasModuleInlineAsm()) {
    Out << '\n';

    for (const Module::GlobalAsmFragment &Frag : M->getModuleInlineAsm()) {
      Out << "module asm";
      SmallVector<std::pair<StringRef, StringRef>> Props =
          Frag.Props.getAsStrings();
      if (!Props.empty()) {
        ListSeparator LS;
        Out << "(";
        for (auto [Key, Value] : Props) {
          Out << LS;
          Out << Key << ": \"";
          printEscapedString(Value, Out);
          Out << "\"";
        }
        Out << ")";
      }
      Out << "\n";
      // Split the string into lines, to make it easier to read the .ll file.
      StringRef Asm = Frag.Asm;
      do {
        StringRef Front;
        std::tie(Front, Asm) = Asm.split('\n');

        // We found a newline, print the portion of the asm string from the
        // last newline up to this newline.
        Out << "    \"";
        printEscapedString(Front, Out);
        Out << "\"\n";
      } while (!Asm.empty());
    }
  }

  printTypeIdentities();

  // Output all comdats.
  if (!Comdats.empty())
    Out << '\n';
  for (const Comdat *C : Comdats) {
    printComdat(C);
    if (C != Comdats.back())
      Out << '\n';
  }

  // Output all globals.
  if (!M->global_empty()) Out << '\n';
  for (const GlobalVariable &GV : M->globals()) {
    printGlobal(&GV); Out << '\n';
  }

  // Output all aliases.
  if (!M->alias_empty()) Out << "\n";
  for (const GlobalAlias &GA : M->aliases())
    printAlias(&GA);

  // Output all ifuncs.
  if (!M->ifunc_empty()) Out << "\n";
  for (const GlobalIFunc &GI : M->ifuncs())
    printIFunc(&GI);

  // Output all of the functions.
  for (const Function &F : *M) {
    Out << '\n';
    printFunction(&F);
  }

  // Output global use-lists.
  printUseLists(nullptr);

  // Output all attribute groups.
  if (!Machine.as_empty()) {
    Out << '\n';
    writeAllAttributeGroups();
  }

  // Output named metadata.
  if (!M->named_metadata_empty()) Out << '\n';

  for (const NamedMDNode &Node : M->named_metadata())
    printNamedMDNode(&Node);

  // Output metadata.
  if (!Machine.mdn_empty()) {
    Out << '\n';
    writeAllMDNodes();

