bool LLParser::parseTopLevelEntities() {
  // If there is no Module, then parse just the summary index entries.
  if (!M) {
    while (true) {
      switch (Lex.getKind()) {
      case lltok::Eof:
        return false;
      case lltok::SummaryID:
        if (parseSummaryEntry())
          return true;
        break;
      case lltok::kw_source_filename:
        if (parseSourceFileName())
          return true;
        break;
      default:
        // Skip everything else
        Lex.Lex();
      }
    }
  }
  while (true) {
    switch (Lex.getKind()) {
    default:
      return tokError("expected top-level entity");
    case lltok::Eof: return false;
    case lltok::kw_declare:
      if (parseDeclare())
        return true;
      break;
    case lltok::kw_define:
      if (parseDefine())
        return true;
      break;
    case lltok::kw_module:
      if (parseModuleAsm())
        return true;
      break;
    case lltok::LocalVarID:
      if (parseUnnamedType())
        return true;
      break;
    case lltok::LocalVar:
      if (parseNamedType())
        return true;
      break;
    case lltok::GlobalID:
      if (parseUnnamedGlobal())
        return true;
      break;
    case lltok::GlobalVar:
      if (parseNamedGlobal())
        return true;
      break;
    case lltok::ComdatVar:  if (parseComdat()) return true; break;
    case lltok::exclaim:
      if (parseStandaloneMetadata())
        return true;
      break;
    case lltok::SummaryID:
      if (parseSummaryEntry())
        return true;
      break;
    case lltok::MetadataVar:
      if (parseNamedMetadata())
        return true;
      break;
    case lltok::kw_attributes:
      if (parseUnnamedAttrGrp())
        return true;
      break;
    case lltok::kw_uselistorder:
      if (parseUseListOrder())
        return true;
      break;
    }
  }
}

/// toplevelentity
///   ::= 'module' 'asm' STRINGCONSTANT
///   ::= 'module' 'asm' '(' 'property_name1:' STRINGCONSTANT ','
///                          'property_name2:' STRINGCONSTANT ')'
///                      STRINGCONSTANT
bool LLParser::parseModuleAsm() {
  assert(Lex.getKind() == lltok::kw_module);
  Lex.Lex();

  std::string AsmStr;
  if (parseToken(lltok::kw_asm, "expected 'module asm'"))
    return true;

  Module::GlobalAsmProperties Props;
  if (EatIfPresent(lltok::lparen)) {
    while (true) {
      std::string Key, Value;
      SMLoc Loc = Lex.getLoc();
      if (Lex.getKind() != lltok::LabelStr)
        return error(Loc, "expected property name followed by ':'");

      Key = Lex.getStrVal();
      Lex.Lex();

      if (parseStringConstant(Value))
        return true;

      if (!Props.set(Key, Value))
        return error(Loc, "unknown property name");

      if (EatIfPresent(lltok::rparen))
        break;
      if (parseToken(lltok::comma, "expected ',' or ')'"))
        return true;
    }
  }

  do {
    std::string AsmStrPart;
    if (parseStringConstant(AsmStrPart))
      return true;
    AsmStr += AsmStrPart + "\n";
  } while (Lex.getKind() == lltok::StringConstant);

  M->appendModuleInlineAsm({AsmStr, Props});
  return false;
}

